create or replace function public.business_create_event(p_business_id uuid,p_title text) returns uuid language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; if not public.business_advanced_allowed(p_business_id) then raise exception 'Business Growth or Enterprise plan required'; end if; insert into public.business_events(business_id,title,created_at) values(p_business_id,trim(p_title),now()) returning id into v_id; return v_id; end; $$;
